                    student_info->age = strdup((const char*)cur->children->content);
                }
            } else if (xmlStrEqual(cur->name, (xmlChar*)"citizenship")) {
                if (cur->children != NULL && cur->children->content != NULL) {
                    student_info->citizenship = strdup((const char*)cur->children->content);
